<?php
require __DIR__.'/config.php';$code=trim($_GET['codigo']??($_SESSION['last_order']??''));$order=null;$items=[];
if($code!==''){$s=db()->prepare("SELECT * FROM pedidos WHERE codigo=?");$s->execute([$code]);$order=$s->fetch();if($order){$i=db()->prepare("SELECT * FROM itens_pedido WHERE pedido_id=?");$i->execute([$order['id']]);$items=$i->fetchAll();}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedido | Loja BY</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">BY</span><span>LOJA BY<small>SUA MARCA, SEU ESTILO</small></span></a><a href="index.php">Voltar à loja</a></header><main class="wrap"><h1>Acompanhar pedido</h1><form method="get" class="card"><div class="field"><label>Código do pedido</label><input name="codigo" value="<?=h($code)?>" placeholder="Ex.: BY261018ABC123" required></div><p><button class="btn">Consultar pedido</button></p></form><?php if($code!==''&&$order):?><div class="card"><div class="notice success">Pedido registrado com sucesso.</div><h2>Pedido <?=h($order['codigo'])?></h2><p>Status: <span class="pill"><?=h($order['status'])?></span></p><p>Cliente: <?=h($order['cliente_nome'])?></p><p>Data: <?=h($order['criado_em'])?></p><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=h($it['produto_nome'])?> — <?=h($it['tamanho'])?> / <?=h($it['cor'])?></td><td><?=$it['quantidade']?></td><td><?=money($it['preco_unitario']*$it['quantidade'])?></td></tr><?php endforeach?></tbody></table></div><h2>Total: <?=money($order['total'])?></h2><p class="muted">Pagamento e entrega devem ser confirmados com a loja até que os serviços correspondentes sejam integrados.</p></div><?php elseif($code!==''):?><div class="notice error">Pedido não encontrado. Confira o código informado.</div><?php endif?></main><footer class="footer">LOJA BY</footer></body></html>
